package br.com.gestao.stock; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/stock") public class StockController{private final StockMovementRepository repo;public StockController(StockMovementRepository r){repo=r;} @GetMapping("/movements") @PreAuthorize("hasRole('ADMIN')") public List<StockMovement> movements(){return repo.findTop100ByOrderByCreatedAtDesc();}}